81	function flattenCourseLessons(course: {
82	  modules: Array<{
83	    id: number;
84	    title: string;
85	    lessons: Array<{ id: number; title: string; moduleId: number }>;
86	  }>;
87	}): FlatLesson[] {
88	  const flat: FlatLesson[] = [];
89	  for (const mod of course.modules) {
90	    for (const lesson of mod.lessons) {
91	      flat.push({
92	        id: lesson.id,
93	        title: lesson.title,
94	        moduleId: mod.id,
95	        moduleTitle: mod.title,
96	      });
97	    }
98	  }
99	  return flat;
100	}
