458	
459	      <div className="flex-1 p-6 lg:p-8">
460	        {/* Breadcrumb */}
461	        <nav className="mb-6 text-sm text-muted-foreground">
462	          <Link to="/courses" className="hover:text-foreground">
463	            Courses
464	          </Link>
465	          <span className="mx-2">/</span>
466	          <Link
467	            to={`/courses/${course.slug}`}
468	            className="hover:text-foreground"
