579	                      </>
580	                    )}
581	                  </Button>
582	                </fetcher.Form>
583	              ) : (
584	                <fetcher.Form method="post">
585	                  <input type="hidden" name="intent" value="mark-complete" />
586	                  <Button disabled={isMarking}>
587	                    <CheckCircle2 className="mr-2 size-4" />
588	                    {isMarking ? "Marking..." : "Mark as Complete"}
