142	export function calculateProgress(
143	  userId: number,
144	  courseId: number,
145	  includeQuizzes: boolean,
146	  weightByDuration: boolean
147	) {
148	  const lessonIds = getCourseLessonIds(courseId);
149	
150	  if (lessonIds.length === 0) return 0;
151	
152	  if (weightByDuration) {
153	    const courseLessons = db
154	      .select({
155	        id: lessons.id,
156	        durationMinutes: lessons.durationMinutes,
157	      })
158	      .from(lessons)
159	      .where(or(...lessonIds.map((id) => eq(lessons.id, id)))!)
160	      .all();
161	
162	    const totalDuration = courseLessons.reduce(
163	      (sum, l) => sum + (l.durationMinutes ?? 1),
164	      0
165	    );
166	
167	    if (totalDuration === 0) return 0;
168	
169	    const completed = db
170	      .select()
171	      .from(lessonProgress)
172	      .where(
173	        and(
174	          eq(lessonProgress.userId, userId),
175	          eq(lessonProgress.status, LessonProgressStatus.Completed),
176	          or(...lessonIds.map((id) => eq(lessonProgress.lessonId, id)))!
177	        )
178	      )
179	      .all();
180	
181	    const completedIds = new Set(completed.map((p) => p.lessonId));
182	
183	    const completedDuration = courseLessons
184	      .filter((l) => completedIds.has(l.id))
185	      .reduce((sum, l) => sum + (l.durationMinutes ?? 1), 0);
186	
187	    return Math.round((completedDuration / totalDuration) * 100);
188	  }
189	
190	  const completedCount = db
191	    .select({ count: sql<number>`count(*)` })
192	    .from(lessonProgress)
193	    .where(
194	      and(
195	        eq(lessonProgress.userId, userId),
196	        eq(lessonProgress.status, LessonProgressStatus.Completed),
197	        or(...lessonIds.map((id) => eq(lessonProgress.lessonId, id)))!
198	      )
199	    )
200	    .get();
201	
202	  return Math.round(((completedCount?.count ?? 0) / lessonIds.length) * 100);
203	}
